-- Migration 0082: consolidate festivals so the calendar shows one
-- canonical entry per festival (with a precise Drikpanchang-sourced
-- date where we have one) instead of one row per celebrating temple.

create table public.festivals (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  month integer not null check (month between 1 and 12),
  secondary_month integer check (secondary_month between 1 and 12),
  exact_date date,
  exact_date_note text,
  drikpanchang_url text,
  description text,
  created_at timestamptz not null default now()
);

create table public.festival_temples (
  festival_id uuid not null references public.festivals(id) on delete cascade,
  temple_id uuid not null references public.temples(id) on delete cascade,
  significance text,
  primary key (festival_id, temple_id)
);

alter table public.festivals enable row level security;
alter table public.festival_temples enable row level security;

create policy "Festivals are publicly readable" on public.festivals for select using (true);
create policy "Festival links are publicly readable" on public.festival_temples for select using (true);
create policy "Moderators manage festivals" on public.festivals for all using (public.is_moderator()) with check (public.is_moderator());
create policy "Moderators manage festival links" on public.festival_temples for all using (public.is_moderator()) with check (public.is_moderator());

grant select on public.festivals, public.festival_temples to anon, authenticated;
grant insert, update, delete on public.festivals, public.festival_temples to authenticated;

insert into public.festivals (slug, name, month, secondary_month, exact_date, exact_date_note, drikpanchang_url, description) values
('akshaya-tritiya', 'Akshaya Tritiya', 4, 5, '2027-05-09', 'Vaishakha Shukla Tritiya — an auspicious day with no need for a muhurat, traditionally when the two Uttarakhand Char Dham temples open for the season.', 'https://www.drikpanchang.com/festivals/akshaya-tritiya/akshaya-tritiya-date-time.html', 'One of the few days considered auspicious for any undertaking without checking a muhurat. For the Uttarakhand Char Dham, it specifically marks the day the winter-closed shrines reopen.'),
('ganesh-chaturthi', 'Ganesh Chaturthi', 8, 9, '2027-09-04', 'Bhadrapada Shukla Chaturthi.', 'https://www.drikpanchang.com/festivals/ganesh-chaturthi/ganesh-chaturthi-date-time.html', 'Ganesha''s birthday, celebrated across the country but nowhere more elaborately than Maharashtra''s Ashtavinayak circuit — the eight temples together form a traditional pilgrimage route, each with its own distinct legend.'),
('maha-shivaratri', 'Maha Shivaratri', 2, 3, '2027-03-06', 'Phalguna Krishna Chaturdashi.', 'https://www.drikpanchang.com/festivals/maha-shivaratri/maha-shivaratri-date-time.html', 'Shiva''s principal festival, observed with a night-long vigil at Jyotirlinga and other Shiva temples nationwide.'),
('navaratri', 'Navaratri', 9, 10, '2026-10-11', 'Ghatasthapana on 11 October 2026; Vijayadashami on 20 October 2026.', 'https://www.drikpanchang.com/hindu-festivals/navratri.html', 'Nine nights honoring the Goddess in her many forms, building to Vijayadashami — the single busiest window of the year at most Devi temples.'),
('kali-puja', 'Kali Puja', 10, 11, '2026-11-08', 'Kartik Amavasya — the same new-moon night as Diwali, observed as Kali''s night across Bengal, Odisha and Assam rather than Lakshmi''s.', 'https://www.drikpanchang.com/diwali/kali-puja/bengal-kalipuja-date-time.html', 'West Bengal''s Diwali-night counterpart — Kali rather than Lakshmi is the night''s focus, marked with all-night worship at the region''s major Kali temples.'),
('champa-shashti', 'Champa Shashti', 11, 12, '2026-12-15', 'Margashirsha Shukla Shashthi — also known as Skanda Shashthi.', 'https://www.drikpanchang.com/marathi/festivals/champa-shashthi/champa-shashthi-date-time.html', 'Kartikeya/Subramanya''s principal festival, marking his defeat of the demon Tarakasura — celebrated as Champa Shashti in Maharashtra and Skanda Shashthi further south.'),
('rama-navami', 'Rama Navami', 3, 4, '2027-04-15', 'Chaitra Shukla Navami — the traditional birth date of Rama.', 'https://www.drikpanchang.com/dashavatara/rama-navami/rama-navami-date-time.html', 'Rama''s birthday, observed at Rama temples nationwide with the biggest crowds at Ayodhya.'),
('thaipusam', 'Thaipusam', 1, 2, '2027-01-22', 'Tamil month of Thai, under the Pushya nakshatra.', 'https://www.drikpanchang.com/festivals/thaipusam/tamil-thaipusam-date.html', 'Murugan''s festival, marked by kavadi-bearing processions — Palani and Thiruparankundram are among the largest gatherings anywhere.'),
('kartik-purnima', 'Kartik Purnima', 11, null, '2026-11-24', 'Also observed as Dev Deepavali.', 'https://www.drikpanchang.com/purnima/kartik/kartik-purnima-date-time.html', 'The year''s most widely observed full-moon day, marked with river bathing and lamp offerings — also called Tripuri or Dev Deepavali Purnima.'),
