  ('shravani-mela', '59b2c023-62a7-4948-841f-bc0b5783bf1c'::uuid, 'Extremely crowded — millions of kanwariyas carry Ganga water here on foot during Shravan.'),
  ('simhastha-kumbh-mela', 'ecb19034-b752-488b-a436-8d7178e17383'::uuid, 'Held roughly every 12 years — extremely crowded when it falls.'),
  ('skanda-sashti', '15f78710-3db4-4efc-b621-b3541c901e3c'::uuid, 'Commemorates the six-day battle in which Murugan defeated Surapadman.'),
  ('thiru-kalyanam', 'a7796d26-ab95-4c0b-bbe6-f29271841ebc'::uuid, null),
  ('thrissur-pooram', 'de14a8a6-660b-4178-9e24-6d6380d85d63'::uuid, 'Kerala''s largest temple festival, famous for its caparisoned elephants and percussion ensembles.'),
  ('vaikathashtami', 'f85e560c-98e3-48b2-99fa-b3adbe711a32'::uuid, null),
  ('vairamudi-brahmotsavam', 'e0f39c38-9c89-45f4-b218-be0d960f7658'::uuid, 'The deity is adorned with a diamond crown (Vairamudi) said to have belonged to Vishnu himself.'),
  ('vasant-panchami', '037d5f0e-9d88-4bcf-80cd-887352ab7965'::uuid, 'Children''s Aksharabhyasam (first-writing) ceremonies are especially popular.'))
